<?php
namespace App\Observers;use App\Models\AuditLog;use Illuminate\Database\Eloquent\Model;
class AuditObserver{public function created(Model$m):void{$this->write('created',$m,[], $m->getAttributes());}public function updated(Model$m):void{$new=$m->getChanges();$old=collect($m->getOriginal())->only(array_keys($new))->all();$this->write('updated',$m,$old,$new);}public function deleted(Model$m):void{$this->write('deleted',$m,$m->getOriginal(),[]);}private function write(string$a,Model$m,array$old,array$new):void{foreach(['password','remember_token']as$key){unset($old[$key],$new[$key]);}AuditLog::create(['user_id'=>auth()->id(),'action'=>$a,'auditable_type'=>$m::class,'auditable_id'=>$m->getKey(),'old_values'=>$old?:null,'new_values'=>$new?:null,'ip'=>app()->runningInConsole()?null:request()->ip()]);}}
